def slot_meaning_compatible(
    provided: Mapping[str, str], target: Mapping[str, str]
) -> bool:
    """Exact match for legacy dicts; prefix covariance on controlled domain_id."""
    if dict(provided) == dict(target):
        return True
    p_domain = provided.get("domain_id")
    t_domain = target.get("domain_id")
    if (
        not p_domain
        or not t_domain
        or not DOMAIN_ID_RE.fullmatch(p_domain)
        or not DOMAIN_ID_RE.fullmatch(t_domain)
    ):
        return False
    if p_domain != t_domain and not p_domain.startswith(t_domain + "."):
        return False
    for key, expected in target.items():
        if key in ("domain_id", "vocab_version"):
            continue
        if provided.get(key) != expected:
            return False
    return True


def build_slot_preset(
    preset: SlotPresetKind,
    *,
    description: str,
    domain_id: str | None = None,
    required: bool = True,
    on_missing: Literal["pause", "fail", "omit"] = "fail",
    fields: Mapping[str, dict[str, Any]] | None = None,
    currency: str | None = None,
    unit: str | None = None,
) -> ValueSlot:
    """Construct a strict Draft 2020-12 ValueSlot from a named preset."""
    default_domains: dict[SlotPresetKind, str] = {
        "monetary_amount": "fin.amount.monetary",
        "ratio_or_rate": "core.scalar.ratio",
        "structured_record": "core.record.object",
        "tabular_rows": "core.table.rows",
        "check_receipt": "core.check.receipt",
        "cited_markdown": "core.document.cited_markdown",
    }
    chosen_domain = domain_id or default_domains[preset]
    if not DOMAIN_ID_RE.fullmatch(chosen_domain):
        raise ValueError("Invalid controlled slot domain_id")
    meaning: dict[str, str] = {"domain_id": chosen_domain, "vocab_version": "1"}
    if currency:
        meaning["currency"] = currency
    if unit:
        meaning["unit"] = unit
    props = dict(fields) if fields else {"key": {"type": "string", "minLength": 1}}
    schemas: dict[SlotPresetKind, dict[str, Any]] = {
        "monetary_amount": {
            "type": "object",
            "required": ["amount", "currency"],
            "additionalProperties": False,
            "properties": {
                "amount": {"type": "number"},
                "currency": {"type": "string", "minLength": 1},
                "period": {"type": "string"},
            },
        },
        "ratio_or_rate": {"type": "number"},
        "structured_record": {
            "type": "object",
            "required": sorted(props.keys()),
            "additionalProperties": False,
            "properties": props,
        },
        "tabular_rows": {
            "type": "array",
            "items": {
                "type": "object",
                "required": sorted(props.keys()),
                "additionalProperties": False,
                "properties": props,
            },
        },
        "check_receipt": {
            "type": "object",
            "required": ["passed", "detail"],
            "additionalProperties": False,
            "properties": {
                "passed": {"type": "boolean"},
                "detail": {"type": "string"},
                "difference": {"type": "number"},
            },
        },
        "cited_markdown": {
            "type": "object",
            "required": ["markdown", "citations"],
            "additionalProperties": False,
            "properties": {
                "markdown": {"type": "string", "minLength": 1},
                "citations": {
                    "type": "array",
                    "items": {
                        "type": "object",
                        "required": ["material_id", "locator", "quote"],
                        "additionalProperties": False,
                        "properties": {
                            "material_id": {"type": "string", "minLength": 1},
                            "locator": {"type": "string", "minLength": 1},
                            "quote": {"type": "string", "minLength": 1},
                        },
                    },
                },
            },
        },
    }
    return ValueSlot.model_validate(
        {
            "description": description,
            "schema": schemas[preset],
            "required": required,
            "meaning": meaning,
            "on_missing": "pause" if required and on_missing == "omit" else on_missing,
        }
    )


