class ValueSlot(Strict):
    description: Text
    schema_: dict[str, Any] = Field(alias="schema")
    required: bool = Field(strict=True)
    meaning: dict[Name, Text] = Field(max_length=20)
    on_missing: Literal["pause", "fail", "omit"]

    def accepts(self, value: Any) -> bool:
        try:
            return Draft202012Validator(self.schema_).is_valid(value)
        except RecursionError:
            # Recursive local schemas can legitimately describe finite trees.
            # A validation that cannot finish never certifies a value.
            return False

    @model_validator(mode="after")
    def valid(self):
        # No remote schema fetching during either incubation or execution.
        def local(value, depth=0):
            if depth > 32:
                raise ValueError("Method value schema exceeds its depth limit")
            if isinstance(value, dict):
                for key, item in value.items():
                    if key in ("$id", "$anchor", "$dynamicAnchor", "$dynamicRef"):
                        raise ValueError("Method schemas use local JSON pointers only")
                    if key == "$ref":
                        if not isinstance(item, str) or not item.startswith("#/"):
                            raise ValueError(
                                "Method value schemas must be self-contained"
                            )
                        target = self.schema_
                        for segment in item[2:].split("/"):
                            segment = segment.replace("~1", "/").replace("~0", "~")
                            if not isinstance(target, dict) or segment not in target:
                                raise ValueError(
                                    "Method schema reference does not exist"
                                )
                            target = target[segment]
                    local(item, depth + 1)
            elif isinstance(value, list):
                for item in value:
                    local(item, depth + 1)

        local(self.schema_)
        if len(json.dumps(self.schema_, allow_nan=False)) > 64000:
            raise ValueError("Method value schema exceeds its size limit")
        try:
            Draft202012Validator.check_schema(self.schema_)
        except SchemaError as exc:
            raise ValueError("Invalid method value schema") from exc
        if self.required and self.on_missing == "omit":
            raise ValueError("A required value cannot be silently omitted")
        return self


class ProjectionLens(Strict):
    """Side-effect-free width projection and field renaming (§2.2 closed value ops)."""

    pick_fields: tuple[Name, ...] = Field(
        default=(), max_length=64, exclude_if=lambda value: not value
    )
    rename_fields: dict[Name, Name] = Field(
        default_factory=dict, max_length=64, exclude_if=lambda value: not value
    )

    @model_validator(mode="after")
    def valid_lens(self):
        if not self.pick_fields and not self.rename_fields:
            raise ValueError("A projection lens requires pick_fields or rename_fields")
        if len(set(self.pick_fields)) != len(self.pick_fields):
            raise ValueError("Duplicate field in pick_fields")
        if self.pick_fields and not set(self.rename_fields).issubset(self.pick_fields):
            raise ValueError("rename_fields keys must be included in pick_fields")
        targets = [self.rename_fields.get(k, k) for k in self.pick_fields] or list(
            self.rename_fields.values()
        )
        if len(set(targets)) != len(targets):
            raise ValueError("Projection lens produces colliding field names")
        return self


def _project_object_schema(
    obj_schema: dict[str, Any], lens: ProjectionLens
) -> dict[str, Any]:
    props = obj_schema.get("properties")
    if obj_schema.get("type") != "object" or not isinstance(props, dict):
        raise ValueError(
            "Projection lens requires an object or array-of-objects schema"
        )
    selected = list(lens.pick_fields) if lens.pick_fields else list(props.keys())
    if not set(selected).issubset(props.keys()) or not set(lens.rename_fields).issubset(
        props.keys()
    ):
        raise ValueError("Projection lens references an absent source property")
    source_req = set(obj_schema.get("required") or ())
    new_props: dict[str, Any] = {}
    new_req: list[str] = []
    for key in selected:
        out_key = lens.rename_fields.get(key, key)
        if out_key in new_props:
            raise ValueError("Projection lens target property collision")
        new_props[out_key] = copy.deepcopy(props[key])
        if key in source_req:
            new_req.append(out_key)
    projected: dict[str, Any] = {
        "type": "object",
        "additionalProperties": obj_schema.get("additionalProperties", False),
        "properties": new_props,
    }
    if new_req:
        projected["required"] = new_req
    return projected


def project_schema(schema: dict[str, Any], lens: ProjectionLens) -> dict[str, Any]:
    """Deterministically project a JSON Schema through a closed ProjectionLens."""
    if schema.get("type") == "array" and isinstance(schema.get("items"), dict):
        out = copy.deepcopy(schema)
        out["items"] = _project_object_schema(schema["items"], lens)
        return out
    return _project_object_schema(schema, lens)


def apply_projection_lens(value: Any, lens: ProjectionLens) -> Any:
    """Apply a ProjectionLens to an object or list of objects without mutation."""

    def transform_one(item: Any) -> dict[str, Any]:
        if type(item) is not dict:
            raise ValueError("Projection lens input must be a JSON object")
        keys = list(lens.pick_fields) if lens.pick_fields else list(item.keys())
        result: dict[str, Any] = {}
        for key in keys:
            if key in item:
                result[lens.rename_fields.get(key, key)] = copy.deepcopy(item[key])
        return result

    if type(value) is list:
        return [transform_one(entry) for entry in value]
    return transform_one(value)


