class VerifiedArtifactGuard(Strict):
    """Deterministic model-free predicate over an accepted predecessor output."""

    step: Name
    output: Name
    pointer: LocalPointer = Field(default="", exclude_if=lambda value: not value)
    op: Literal["eq", "ne", "gt", "gte", "lt", "lte", "in_set", "is_present"]
    value: Any = Field(default=None, exclude_if=lambda value: value is None)

    @model_validator(mode="after")
    def valid_guard(self):
        json.dumps(self.value, allow_nan=False)
        if self.op == "is_present":
            if self.value is not None:
                raise ValueError("is_present guard does not take a comparison value")
        elif self.op == "in_set":
            if not isinstance(self.value, list) or not 1 <= len(self.value) <= 64:
                raise ValueError(
                    "in_set guard requires a non-empty list up to 64 items"
                )
        elif self.op in ("gt", "gte", "lt", "lte"):
            if type(self.value) not in (int, float):
                raise ValueError(
                    "Numeric comparison guard requires a numeric threshold"
                )
        elif self.value is None and self.op not in ("eq", "ne"):
            raise ValueError("Guard requires a comparison value")
        return self


class MethodStep(Strict):
    candidate_choice: CandidateChoice | None = Field(
        default=None, exclude_if=lambda value: value is None
    )
    artifact_guard: VerifiedArtifactGuard | None = Field(
        default=None, exclude_if=lambda value: value is None
    )
    step_batch: ObjectBatch | None = Field(
        default=None, exclude_if=lambda value: value is None
    )
    id: Name
    candidates: tuple[MethodRef, ...] = Field(min_length=1, max_length=100)
    select_when: Text
    required_when: Text
    always_required: bool = Field(strict=True)
    depends_on: tuple[Name, ...] = Field(max_length=100)
    inputs: dict[Name, StepInput] = Field(max_length=100)
    outputs: dict[Name, ValueSlot] = Field(min_length=1, max_length=100)
    on_failure: Literal["pause", "fail"]

    @model_validator(mode="after")
    def valid(self):
        refs = [(r.method_id, r.version) for r in self.candidates]
        if len(refs) != len(set(refs)):
            raise ValueError("Duplicate method candidate version")
        if self.artifact_guard is not None:
            if self.always_required:
                raise ValueError(
                    "A guarded conditional step cannot be marked always_required"
                )
            if self.artifact_guard.step not in self.depends_on:
                raise ValueError(
                    "Artifact guard must reference a declared predecessor step"
                )
        choice = self.candidate_choice
        if choice is not None:
            port = self.inputs.get(choice.input)
            if (
                not self.always_required
                or port is None
                or not port.slot.required
                or not isinstance(port.binding, CallerValue)
                or port.slot.schema_.get("type") != "string"
            ):
                raise ValueError(
                    "Candidate selection needs a mandatory caller string input"
                )
            values = {case.equals for case in choice.cases}
            if len(values) != len(choice.cases) or not all(
                port.slot.accepts(v) for v in values
            ):
                raise ValueError(
                    "Case values must be distinct and accepted by the input"
                )
            mapped = tuple(case.candidate for case in choice.cases)
            if len(mapped) != len(self.candidates) or any(
                ref not in mapped for ref in self.candidates
            ):
                raise ValueError("Every case must bind a distinct pinned candidate")
        if len(self.depends_on) != len(set(self.depends_on)):
            raise ValueError("Duplicate step dependency")
        return self


