def _has_relative_ref(value: Any) -> bool:
    if isinstance(value, dict):
        return "$ref" in value or any(_has_relative_ref(v) for v in value.values())
    return isinstance(value, list) and any(_has_relative_ref(v) for v in value)


def _pack_value_schema_matches(
    member_schema: dict[str, Any],
    pack_value_schema: Any,
    allow_skipped: bool,
) -> bool:
    if member_schema == pack_value_schema:
        return True
    if allow_skipped and isinstance(pack_value_schema, dict):
        for union_key in ("anyOf", "oneOf"):
            options = pack_value_schema.get(union_key)
            if (
                isinstance(options, list)
                and len(options) == 2
                and member_schema in options
                and {"type": "null"} in options
            ):
                return True
    return False


class Orchestration(Strict):
    object_batch: ObjectBatch | None = Field(
        default=None, exclude_if=lambda value: value is None
    )

    collaboration: CollaborationRoles | None = Field(
        default=None,
        min_length=1,
        max_length=100,
        exclude_if=lambda value: value is None,
    )

    kind: Literal["orchestration"]
    instructions: Text
    steps: tuple[MethodStep, ...] = Field(min_length=1, max_length=100)
    exports: dict[Name, Export] = Field(min_length=1, max_length=100)
    max_depth: int = Field(strict=True, ge=1, le=16)
    max_expansions: int = Field(strict=True, ge=1, le=1000)
    max_steps: int = Field(strict=True, ge=1, le=1000)
